 80	\begin{lemma}[Orthogonality of finite-field characters]\label{lem:character-average-vector}
 81		\lean{MIPStarRE.LDT.Preliminaries.fourier_fact_vector}
 82		\leanok
 83		For $\alpha,\beta \in \F_q^m$,
 84		\[
 85			\frac{1}{q^m}\sum_{u \in \F_q^m} \omega^{\operatorname{tr}(u\cdot(\beta-\alpha))} =
 86			\begin{cases}
 87				1 & \text{if } \alpha=\beta,    \\
 88				0 & \text{if } \alpha\ne \beta.
 89			\end{cases}
 90		\]
 91	\end{lemma}
 92	\begin{proof}
 93		\leanok
 94		\uses{prop:fourier-fact-vector}
 95		This is Lemma~\ref{prop:fourier-fact-vector} applied to $v=\beta-\alpha$.
 96	\end{proof}
